mapper.update:
update /* com.seinfo.protoA.component.main.mapper.LoginMapper.updateUsrLoginFail */
	seinfo_vendor_manager
   set fail_cnt  	= #{failCnt }
	 , fail_dt   	= now()
	 , mod_dt		= now()
	 , mod_user_id  = #{userEmail}
 where user_uid = #{userUid}

update /* com.seinfo.protoA.component.main.mapper.LoginMapper.updateUsrTempPwd */
		seinfo_vendor_manager
   set user_pwd 		= #{crytPwd}
     , user_pwd_init_yn = 'Y'
     , fail_cnt			= 0
     , fail_dt          = null
     , mod_dt           = now()
     , mod_user_id  	= #{userEmail}
where user_uid = #{userUid}

update /* com.seinfo.protoA.component.main.mapper.LoginMapper.updateUserPwd */
		seinfo_vendor_manager
   set user_pwd 		= #{crytPwd}
	 , user_pwd_init_yn = 'N'
	 , fail_cnt			= 0
	 , user_pwd_ch_d 	= now()
	 , user_login_d     = now()
	 , mod_dt			= now()
	 , mod_user_id  	= #{userEmail}
where user_uid = #{userUid}

mapper.select:
SELECT /* com.seinfo.protoA.component.main.mapper.LoginMapper.findUsrEmail */
       user_uid
	 , user_email
  FROM seinfo_vendor_manager
 WHERE user_phone = #{userPhone}
   AND user_nm    = #{userNm}
